/* L6 · extends the L5 project, shared shell and overlay; offline demonstration only. */
(function(CF){
  'use strict';
  const D=CF.LS,S=CF.S,L=CF.L,E=CF.esc,H=3600000,KEY='hc-ws352-v1';
  const Q=CF.CQ={};
  ['P-LS-04','P-LS-05','P-LS-06'].forEach(id=>CF.PAGES[id]={end:'asset',layout:'portal',parent:'P-LS-02',presentation:'modal'});
  let db,flow={},busy=false,problem='',problemCopy=['',''],invalid='',fault='normal',fund='fund-a',wallet=true,focusBack=null;
  const files=new Map();
  const creditFiles=new Map();
  let companyState='complete';
  const creditTitle=m=>L({new:'Establish credit',increase:'Increase credit',renew:'Reassess credit'}[m],{new:'首次核定',increase:'追加授信',renew:'到期重新核定'}[m]);
  const creditRelated=c=>!!c&&(S.role==='fund'&&c.fund===fund||S.role==='asset'&&D.mine({owner:c.owner}));
  const creditWritable=()=>S.role==='fund'&&flow.fund===fund&&pFlow()?.owner;
  const creditDirty=()=>flow.stage==='credit'&&(flow.total!==flow.initial?.total||flow.expires!==flow.initial?.expires||flow.remark!==''||flow.agreements?.length>0);
  const fileSize=n=>n>=1048576?(n/1048576).toFixed(2)+' MB':Math.max(0.01,n/1024).toFixed(2)+' KB';
  function renderCredit(){
    const body=document.querySelector('.modal-b'),top=body?.scrollTop||0,focus=document.activeElement?.id;
    CF.render();
    if(focus)document.getElementById(focus)?.focus({preventScroll:true});
    const next=document.querySelector('.modal-b');if(next)next.scrollTop=top;
  }
  function closeFlow(){
    (flow.agreements||[]).forEach(f=>{if(!flow.creditSaved)creditFiles.delete(f.id);});
    flow={};save();CF.closeLayer();
    setTimeout(()=>document.querySelector('[data-act="'+focusBack+'"]')?.focus({preventScroll:true}),0);
  }
  function requestClose(){if(creditDirty()){flow.discard=true;renderCredit();}else closeFlow();}
  function companyView(){
    const state=companyState,missing=L('Not provided','暂未提供');
    if(state==='loading')return '<div id="cq-enterprise" tabindex="-1" role="status" class="cq-company-state">'+L('Loading company information…','正在加载企业资料…')+'</div>';
    if(state==='error')return '<div id="cq-enterprise" tabindex="-1" class="cq-company-state">'+note('Company information could not be loaded.','企业资料加载失败。','warn')+B('company-retry','Retry','重新加载')+'</div>';
    if(state==='unconfirmed'||state==='denied')return '<div id="cq-enterprise" tabindex="-1">'+note(state==='denied'?'You do not have permission to act for this company.':'The project owner could not be confirmed. Retry later.',state==='denied'?'您无权为该企业办理授信。':'暂时无法确认项目所属企业，请稍后重试。','red')+'</div>';
    const partial=state==='partial',a=pFlow().owner==='entity-demo-a';
    return '<div class="cq-company"><strong>'+ (partial?L('Company name not provided','企业名称暂未提供'):company(pFlow()))+'</strong>'+(!partial?'<span class="hint">'+(a?'Demo Asset Company A':'Demo Asset Company B')+'</span>':'')+'</div>'+dl([[L('Registered country / region','注册国家 / 地区'),partial?missing:L('Singapore','新加坡')],[L('Registration number (UEN)','企业登记号码（UEN）'),partial?missing:(a?'DEMO-REG-A':'DEMO-REG-B')]])+'<details class="ls-history"><summary>'+L('Registered address','注册地址')+'</summary><p>'+ (partial?missing:L('Example address · 18 Example Avenue, #08-01, Singapore 000000','示例地址 · 18 Example Avenue, #08-01, Singapore 000000'))+'</p></details>';
  }
  function retryCompany(){companyState='loading';const draft=flow;setTimeout(()=>{if(flow!==draft)return;companyState='complete';renderCredit();},650);}
  function agreementList(){
    const list=flow.agreements||[];
    return '<div class="cq-upload-head"><label for="cq-agreements">'+L('Agreement files *','协议文件 *')+'</label><span class="mono" aria-live="polite">'+list.filter(f=>f.state==='success').length+' / 10 '+L('uploaded','已上传')+'</span></div><p class="hint">'+L('1–10 PDF, JPG or PNG files · up to 10 MB each','1～10 份 PDF、JPG 或 PNG · 每份不超过 10 MB')+'</p><label class="cq-upload-picker" for="cq-agreements"><span>'+L('Choose agreements','选择协议文件')+'</span><span class="hint">'+L('Slots remaining: ','还可添加 ')+(10-list.length)+L('',' 份')+'</span><input class="cq-file-input" id="cq-agreements" type="file" accept=".pdf,.jpg,.jpeg,.png" multiple aria-label="'+L('Choose credit agreements','选择授信协议')+'"'+(busy?' disabled':'')+'></label><ul class="cq-files cq-agreement-files" aria-live="polite">'+list.map(f=>'<li><div class="cq-file-meta"><b>'+E(f.name)+'</b><span class="hint">'+fileSize(f.size)+' · '+L({uploading:'Uploading',success:'Uploaded',failed:'Upload failed'}[f.state],{uploading:'上传中',success:'已上传',failed:'上传失败'}[f.state])+'</span>'+(f.state==='uploading'?'<progress max="100" value="'+f.progress+'" aria-label="'+L('Upload progress','上传进度')+'"></progress>':'')+'</div><div class="cq-file-actions">'+(f.state==='success'?B('credit-preview','Preview','预览',f.id)+B('credit-download','Download','下载',f.id):f.state==='failed'?B('credit-retry','Retry','重试',f.id):'')+B('credit-remove',f.state==='uploading'?'Cancel upload':'Remove',f.state==='uploading'?'取消上传':'移除',f.id)+'</div></li>').join('')+'</ul>'+(invalid==='agreements'?err():'');
  }
  function creditHistory(c){
    if(!creditRelated(c))return '';
    if(!c.history?.length)return '<p class="hint">'+L('No agreements provided for this historical record.','历史记录未提供协议')+'</p>';
    return [...c.history].reverse().map(h=>'<article class="cq-credit-history"><div class="ls-row"><b>'+creditTitle(h.mode)+'</b><span class="hint">'+time(h.at)+'</span></div>'+dl([[L('Credit limit / valid until','授信额度 / 有效期至'),usd(h.total)+' · '+date(h.expires)],[L('Funder','核定机构'),institution(c.fund)]])+(h.remark&&S.role==='fund'&&c.fund===fund?'<p>'+L('Internal remark: ','内部备注：')+E(h.remark)+'</p>':'')+(h.agreements?.length?'<ul class="cq-files cq-agreement-files">'+h.agreements.map(f=>'<li><div class="cq-file-meta"><b>'+E(f.name)+'</b><span class="hint">'+fileSize(f.size)+(creditFiles.has(f.id)?'':L(' · Local file unavailable',' · 本地文件不可用'))+'</span></div><div class="cq-file-actions">'+B('credit-preview','Preview','预览',f.id,false,!creditFiles.has(f.id))+B('credit-download','Download','下载',f.id,false,!creditFiles.has(f.id))+'</div></li>').join('')+'</ul>':'<p class="hint">'+L('No agreements provided for this historical record.','历史记录未提供协议')+'</p>')+'</article>').join('');
  }
  function creditEditor(){
    const p=pFlow(),c=credit(p),increase=flow.mode==='increase';
    const conditions=(increase?'<div class="cq-credit-metrics">'+dl([[L('Current limit','当前额度'),usd(c.total)],[L('Available credit','当前可用授信'),usd(available(c))],[L('Shortfall for this quote','本次报价差额'),usd(Math.max(0,D.current(p).amount-available(c)))]])+'</div>':'')+'<div class="cq-grid">'+field('total',increase?'Increase amount (USD) *':'Credit limit (USD) *',increase?'增加额（USD）*':'授信额度（USD）*',flow.total,'text','inputmode="decimal"')+'<div>'+field('expires','Credit valid until *','授信有效期至 *',flow.expires,'date',increase?'min="'+c.expires+'"':'min="'+anniversary(1)+'" max="'+anniversary(5)+'"')+'<p class="hint">'+(increase?L('Current: ','当前：')+date(c.expires)+' · '+L('Keep or extend','可保持或延后'):date(anniversary(1))+' — '+date(anniversary(5)))+'</p></div></div>'+(increase?'<p id="cq-adjusted" class="cq-adjusted">'+L('Adjusted limit: ','调整后额度：')+usd(c.total+Number(flow.total||0))+'</p>':flow.mode==='renew'?'<p class="hint">'+L('Previous expiry: ','原到期日：')+date(c.expires)+'</p>':'')+(['total','expires'].includes(invalid)?err():'')+field('remark','Internal remark (optional)','内部备注（选填）',flow.remark,'text','maxlength="200"')+(c?'<details class="ls-history"><summary>'+L('Existing credit and agreements','既有授信与协议')+'</summary>'+creditInfo(p)+creditHistory(c)+'</details>':'');
    return (flow.discard?'<div class="cq-discard" role="alert"><b>'+L('Discard unsaved credit changes?','放弃未保存的授信修改？')+'</b><p>'+L('Entered terms and new uploads will be discarded.','填写的授信条件及本次上传文件将被放弃。')+'</p><div class="ls-row">'+B('keep-editing','Continue editing','继续编辑','',true)+B('discard-credit','Discard changes','放弃修改')+'</div></div>':'')+'<div class="ls-row cq-mode">'+CF.tag('accent',creditTitle(flow.mode))+'<span class="hint">'+institution(fund)+'</span></div>'+section(L('Company information','企业基本信息'),companyView()+(invalid==='enterprise'?err():''))+section(L('Credit terms','授信条件'),conditions)+section(L('Credit agreements','授信协议'),agreementList())+'<p class="hint">'+L('Credit takes effect on save. You can then review and submit a financing quote.','保存后授信即生效，随后填写并确认融资报价。')+'</p>'+(!['total','expires','agreements','enterprise'].includes(invalid)?err():'');
  }
  function uploadAgreement(f){
    const draft=flow,fail=fault==='uploadFailure';if(fail)fault='normal';
    f.state='uploading';f.progress=20;const attempt=f.attempt=(f.attempt||0)+1;
    const live=()=>flow===draft&&flow.agreements.includes(f)&&f.attempt===attempt;
    setTimeout(()=>{if(live()){f.progress=65;renderCredit();}},250);
    setTimeout(()=>{if(live()){f.state=fail?'failed':'success';f.progress=100;renderCredit();}},700);
  }
  function pickAgreements(selected){
    if(flow.stage!=='credit'||!creditWritable()||busy)return;
    problem='';invalid='';
    if(flow.agreements.length+selected.length>10){failure('This selection exceeds the limit. You can add '+(10-flow.agreements.length)+' more files.','本批文件超出数量上限，还可添加 '+(10-flow.agreements.length)+' 份；已保留原有文件。','agreements');renderCredit();return;}
    const rejected=[];
    selected.forEach(file=>{
      if(!/\.(pdf|jpe?g|png)$/i.test(file.name)||!['application/pdf','image/jpeg','image/png',''].includes(file.type))rejected.push(file.name+L(' (unsupported format)','（格式不支持）'));
      else if(file.size===0||file.size>10*1024*1024)rejected.push(file.name+(file.size===0?L(' (empty file)','（空文件）'):L(' (over 10 MB)','（超过 10 MB）')));
      else{const f={id:'credit-file-'+(++db.serial),name:file.name,size:file.size};flow.agreements.push(f);creditFiles.set(f.id,file);uploadAgreement(f);}
    });
    if(rejected.length)failure('Not added: '+rejected.join('; '),'未添加：'+rejected.join('；'),'agreements');
    renderCredit();
  }
  function submitCredit(){
    const p=pFlow(),c=credit(p),num=Number(flow.total),total=flow.mode==='increase'&&c?c.total+num:num;
    if(!creditWritable()||['unconfirmed','denied'].includes(companyState))return failure('The company or your permission cannot be confirmed.','无法确认企业归属或您的办理权限。','enterprise');
    if(!/^\d+(\.\d{1,2})?$/.test(flow.total)||!Number.isFinite(total)||num<=0||c&&(total<c.total||total<c.principal+used(c)))return failure('Enter a positive amount with up to 2 decimal places; the credit limit cannot decrease.','请输入大于 0、最多两位小数的金额；额度不得调低或低于已用额。','total');
    if(!/^\d{4}-\d{2}-\d{2}$/.test(flow.expires))return failure('Choose the credit expiry date.','请选择授信有效期。','expires');
    if(flow.mode==='increase'){
      if(flow.expires<c.expires)return failure('The expiry date cannot be earlier than the current date.','不得早于当前授信有效期。','expires');
      if(flow.expires>c.expires)return failure('The extension limit cannot be verified at this time. Keep the current date or retry later.','暂时无法校验延期上限，请保持原有效期或稍后重试。','expires');
    }else if(flow.expires<anniversary(1)||flow.expires>anniversary(5))return failure('Choose a date between '+anniversary(1)+' and '+anniversary(5)+'.','有效期须在 '+anniversary(1)+' 至 '+anniversary(5)+' 之间。','expires');
    if(!flow.agreements.length||flow.agreements.some(f=>f.state!=='success'))return failure('Upload at least one agreement. Wait for pending uploads; retry or remove failed files.','请至少上传一份协议；等待上传完成，并重试或移除失败文件。','agreements');
    asyncAction(()=>{
      if(!creditWritable()||['unconfirmed','denied'].includes(companyState)){failure('Permission changed. No credit was saved.','权限已变化，未保存授信。','enterprise');return;}
      const record=c||{id:'CR-DEMO-'+(++db.serial),owner:p.owner,fund,principal:0,first:D.iso(),history:[]};
      record.history.push({at:D.iso(),mode:flow.mode,total,expires:flow.expires,remark:flow.remark,agreements:flow.agreements.map(({id,name,size})=>({id,name,size}))});
      record.total=total;record.expires=flow.expires;if(!c)db.credits.push(record);flow.creditSaved=true;flow.agreements=[];flow.discard=false;
      CF.toast(L('Credit is now effective.','授信已生效。'));
      if(canQuote(p)&&checkCoverage(p)){if(available(record)<D.current(p).amount){creditForm('increase');failure('Credit is effective but still insufficient. Add credit for the updated shortfall.','授信已生效，但额度仍不足，请按最新差额继续追加。');}else flow.stage='quote';}else flow.stage='unavailable';
    });
  }
  function creditFileAction(id,previewOnly){
    const draft=flow.stage==='credit'&&creditWritable()&&flow.agreements?.some(f=>f.id===id&&f.state==='success');
    const historical=db.credits.some(c=>creditRelated(c)&&c.history?.some(h=>h.agreements?.some(f=>f.id===id)));
    if(!draft&&!historical){CF.toast(L('You cannot access this agreement.','您无权访问该协议。'));return;}
    const file=creditFiles.get(id);if(!file){CF.toast(L('The local file is unavailable.','本地文件不可用，请向经办人索取原件。'));return;}
    const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;
    if(previewOnly){a.target='_blank';a.rel='noopener';}else a.download=file.name;
    a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);
  }
  function creditOverview(p){
    const list=db.credits.filter(c=>c.owner===p.owner&&creditRelated(c));if(!list.length)return '';
    return '<section class="card"><div class="card-head"><h2 class="ls-subheading">'+L('Credit and agreements','授信与协议')+'</h2></div><div class="card-b">'+list.map(c=>'<details class="ls-history"><summary>'+institution(c.fund)+' · '+usd(c.total)+' · '+L('Valid until ','有效期至 ')+date(c.expires)+'</summary>'+creditHistory(c)+'</details>').join('')+'</div></section>';
  }
  const company=p=>p.owner==='entity-demo-a'?L('Demo Asset Company A','演示资产企业 A'):L('Demo Asset Company B','演示资产企业 B');
  const institution=id=>id==='fund-b'?L('Demo Capital B','演示资金机构 B'):L('Demo Capital A','演示资金机构 A');
  const usd=n=>CF.fmtAmt(n)+' USD',time=n=>CF.fmtTime(typeof n==='number'?new Date(n).toISOString():n),date=n=>CF.fmtDate(n);
  const pNow=()=>D.project(decodeURIComponent((location.hash.match(/\/project\/([^?]+)/)||[])[1]||''));
  const pFlow=()=>D.project(flow.project),qFlow=()=>db.quotes.find(q=>q.id===flow.quote);
  const active=p=>db.quotes.find(q=>q.project===p.id&&['waiting','funding'].includes(q.state));
  const related=q=>S.role==='asset'&&D.mine(D.project(q.project))||S.role==='fund'&&q.fund===fund;
  const credit=p=>db.credits.filter(c=>c.owner===p.owner&&c.fund===fund).sort((a,b)=>Date.parse(a.first)-Date.parse(b.first))[0];
  const used=c=>db.quotes.filter(q=>q.owner===c.owner&&q.fund===c.fund&&['waiting','funding'].includes(q.state)).reduce((n,q)=>n+q.amount,0);
  const available=c=>c?Math.max(0,c.total-c.principal-used(c)):0;
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));}catch(_){}D.save();};
  const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:S.tz||'UTC',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(D.now()));
  function anniversary(years){const n=new Date(day()+'T12:00:00Z');n.setUTCFullYear(n.getUTCFullYear()+years);return n.toISOString().slice(0,10);}
  function reset(){db={quotes:[],credits:[],serial:10,lastAccounts:{},events:[]};const p=D.project('FP-DEMO-003'),d=p&&D.current(p);if(d?.state==='quoted'){const at=Date.parse(d.quoteAt);db.quotes.push({id:'FB-DEMO-0001',project:p.id,owner:p.owner,demand:d.id,amount:d.amount,ccy:'USD',rate:'6.40',settlement:d.amount,fx:{value:1,version:'FX-DEMO-001',at,source:['Token issuance platform · demo','代币发行平台 · 演示']},at,end:at+168*H,state:'waiting',fund:'fund-a',repay:p.expires,progress:{account:{},step:1,confirmed:false,viewed:false,declared:false,uploads:[]}});d.institution=['Demo Capital A','演示资金机构 A'];}db.credits.push({id:'CR-DEMO-0001',owner:'entity-demo-a',fund:'fund-a',total:1500000,principal:100000,expires:anniversary(1),first:D.iso(),history:[]});save();}
  try{db=JSON.parse(localStorage.getItem(KEY));if(!db?.quotes)reset();}catch(_){reset();}
  Q.data=()=>db;
  Q.hasHistory=p=>db.quotes.some(q=>q.project===p.id);
  Q.quoteAvailable=p=>{const n=D.numbers(p),d=D.current(p);return !!(d?.state==='open'&&!D.terminal(p)&&!p.expired&&n.limit>=p.balance+n.fly);};
  const originalActions=D.actions;D.actions=p=>({...originalActions(p),quote:S.role==='fund'&&Q.quoteAvailable(p)});
  const B=(act,en,zh,value='',primary=false,off=false)=>'<button type="button" class="btn'+(primary?' primary':'')+'" data-act="cq-'+act+'" data-v="'+E(value)+'"'+(off?' disabled':'')+'>'+L(en,zh)+'</button>';
  const note=(en,zh,t='accent')=>CF.note(t,L(en,zh));
  const err=()=>problem?'<div id="cq-error" role="alert">'+CF.note('red',L(...problemCopy))+(invalid==='name'?B('profile','Update registered name','补登企业名称'):'')+'</div>':'';
  const dl=rows=>'<dl class="dl cq-dl">'+rows.map(r=>'<dt>'+r[0]+'</dt><dd>'+r[1]+'</dd>').join('')+'</dl>';
  const section=(title,html)=>'<section class="cq-section"><h3>'+title+'</h3>'+html+'</section>';
  const field=(key,en,zh,value='',type='text',extra='')=>'<div class="field"><label for="cq-'+key+'">'+L(en,zh)+'</label><input class="inp" id="cq-'+key+'" data-cq-field="'+key+'" type="'+type+'" value="'+E(value)+'" '+extra+(invalid===key?' aria-invalid="true" aria-describedby="cq-error"':'')+'></div>';
  const check=(key,en,zh,on)=>'<label class="cq-check"><input type="checkbox" data-cq-check="'+key+'" '+(on?'checked':'')+'>'+L(en,zh)+'</label>';
  const status=q=>L({waiting:'Awaiting acceptance',funding:'Awaiting disbursement',rejected:'Rejected',expired:'Quote expired'}[q.state],{waiting:'待接受',funding:'待放款',rejected:'已拒绝',expired:'报价已失效'}[q.state]);
  const reason=q=>q.reason==='timeout'?L('Validity period ended','有效期届满'):q.reason==='coverage'?L('Financing request expired','所属融资需求失效'):E(q.reason||'');
  function countdown(q){if(q.state!=='waiting')return '';const min=Math.max(0,Math.ceil((q.end-D.now())/60000)),hours=Math.floor((D.now()-q.at)/H);return '<div class="cq-clock" data-cq-quote="'+E(q.id)+'">'+CF.tag(min<1440?'warn':'',L('Remaining: ','剩余有效期：')+(min<1440?min+L(' min',' 分钟'):Math.ceil(min/60)+L(' h',' 小时')))+'<span>'+L('Locked for ','已锁定 ')+hours+L(' h',' 小时')+'</span><span>'+L('Expires: ','到期：')+time(q.end)+'</span></div>';}
  function snapshot(q){return dl([[L('Exchange rate','汇率'),'1 '+q.ccy+' = '+q.fx.value+' USD'],[L('Effective at','生效时间'),time(q.fx.at)],[L('Rate source','汇率来源'),L(...q.fx.source)],[L('Version','版本标识'),E(q.fx.version)]]);}
  function terms(q,summary=false){const p=D.project(q.project),n=D.numbers(p);return dl([[L('Financing business ID','融资业务编号'),E(q.id)],[L('Request ID','需求编号'),E(q.demand)],[L('Project ID','融资项目编号'),E(q.project)],[L('Asset holder','资产方'),company(p)],[L('Funder','资金方'),institution(q.fund)],[L('Financing amount','融资金额'),usd(q.amount)],[L('Settlement amount','结算金额'),CF.fmtAmt(q.settlement)+' '+q.ccy],[L('Annual interest rate','年化利率'),q.rate+'%'],[L('Repayment type','还款类型'),L('Quarterly interest; principal and remaining interest at maturity','按季付息；到期还本付息')],[L('Final repayment date','最终还款日'),date(q.repay)],[L('Quoted at / lock started','报价时间 / 锁定起始'),time(q.at)],[L('Current eligible collateral','当前有效抵押物'),n.valid.length+L(' tokens · ',' 张 · ')+usd(n.value)]])+snapshot(q)+(summary?fees(q)+note('This summary is not a contract and has no legal effect.','本摘要不是合同，不产生法律效力。'):'');}
  const fees=q=>note('You bear cross-border remittance, intermediary and receiving fees. The received amount will be lower; principal remains '+usd(q.amount)+'.','跨境汇出、中转、入账手续费由您承担；到账金额会少于融资金额，但偿还本金仍按融资金额 '+usd(q.amount)+' 计算。','warn');
  function notify(q,event){const recipients=event==='submitted'||event==='expiring'?['asset']:event==='expired'?['asset',q.fund]:[q.fund];recipients.forEach(who=>{if(!db.events.some(e=>e.quote===q.id&&e.event===event&&e.who===who))db.events.push({quote:q.id,event,who,at:D.now()});});}
  function finish(q,state,why,at=D.now()){if(q.state!=='waiting')return;const p=D.project(q.project),d=p.demands.find(d=>d.id===q.demand);q.state=state;q.reason=why;q.done=at;if(state==='funding'){d.state='funding';p.state='financing';}else if(d.state==='quoted'){d.state='open';d.institution=null;d.quoteAt=null;d.rate=null;d.tenorDays=null;p.state=p.balance?'financing':'raising';}notify(q,state==='rejected'?'rejected':state==='expired'?'expired':'accepted');save();}
  Q.sweep=()=>{let changed=false;db.quotes.filter(q=>q.state==='waiting').forEach(q=>{const p=D.project(q.project),d=p?.demands.find(d=>d.id===q.demand);if(!d)return;if(d.state==='ended'){finish(q,'expired','coverage');changed=true;}else if(D.now()>=q.end){finish(q,'expired','timeout',q.end);changed=true;}else if(q.end-D.now()<=24*H){const count=db.events.length;notify(q,'expiring');if(db.events.length!==count){save();changed=true;}}});return changed;};
  const originalRecompute=D.recompute;D.recompute=p=>{originalRecompute(p);Q.sweep();};
  const originalSeed=D.seed;D.seed=()=>{originalSeed();reset();};
  function failure(en,zh,key=''){problem=L(en,zh);problemCopy=[en,zh];invalid=key;return false;}
  function canQuote(p){if(S.role!=='fund'||flow.fund&&flow.fund!==fund)return failure('Only the current funder may quote.','仅资金方可报价。');const d=D.current(p);if(!d||d.state!=='open'||active(p))return failure('This request is no longer open for quotes.','当前需求已不再接受报价，请查看最新状态。');const c=credit(p);if(c&&c.principal+used(c)>c.total)return failure('Credit usage exceeds the limit. New quotes are paused; contact platform operations.','授信已用额超过额度，已暂停新增报价，请联系平台运营处理。');if(p.expired||D.now()>=Date.parse(p.expires))return failure('The project term has ended.','项目已到期，无法新增报价。');return true;}
  function checkCoverage(p,terminal=false){if(fault==='coverageUnavailable')return failure('Coverage cannot be checked now. Retry later.','暂时无法完成覆盖校验，请稍后重试。');if(fault==='coverage'&&terminal){D.tokens.filter(t=>t.pool===p.id).forEach(t=>t.valid=false);D.recompute(p);fault='normal';}const n=D.numbers(p);if(n.limit<p.balance+n.fly){D.recompute(p);}if(!D.current(p)||D.current(p).state!=='open')return failure('The financing request expired because collateral coverage is insufficient. The asset holder must add collateral and publish a new request.','该融资需求已失效（池内覆盖不足），请待资产方补足覆盖并重新发布。');return true;}
  function mode(p){const c=credit(p);return !c?'new':c.expires<day()?'renew':available(c)<D.current(p).amount?'increase':'quote';}
  function creditForm(m){const p=pFlow(),c=credit(p);flow.mode=m;flow.stage='credit';flow.total=m==='renew'?String(c.total):'';flow.expires=m==='increase'?c.expires:anniversary(1);flow.remark='';flow.agreements=[];flow.creditSaved=false;flow.discard=false;flow.initial={total:flow.total,expires:flow.expires};if(companyState==='loading')retryCompany();}
  function open(stage){problem='';invalid='';flow.stage=stage;CF.openLayer('modal','cq-flow');}
  function startQuote(p){flow={project:p.id,fund,ccy:'',rate:'',stage:'quote'};if(!canQuote(p)||!checkCoverage(p)){CF.toast(problem);return;}flow.mode=mode(p);focusBack='ls-quote';open(flow.mode==='quote'?'quote':'intent');if(flow.mode==='quote'&&companyState==='loading')retryCompany();}
  function beginReview(q){Q.sweep();if(!q||!related(q)||S.role!=='asset'){CF.toast(L('You cannot respond to this quote.','您无权处理该报价。'));return;}if(q.state!=='waiting'){CF.toast(status(q)+' · '+reason(q));return;}flow={project:q.project,quote:q.id};focusBack='ls-handoff';open('respond');}
  function creditInfo(p){const c=credit(p);return c?dl([[L('Credit ID','授信编号'),E(c.id)],[L('Credit limit','授信额度'),usd(c.total)],[L('Outstanding principal','授信占用额'),usd(c.principal)],[L('In-flight quotes','在途报价金额'),usd(used(c))],[L('Total credit used','授信已用额'),usd(c.principal+used(c))],[L('Available credit','可用授信'),usd(available(c))],[L('Valid until','有效期至'),date(c.expires)],[L('First established','首次核定时间'),time(c.first)]]):'';}
  function difference(p){const amount=D.current(p)?.amount||0,a=available(credit(p));return '<p class="cq-difference mono">'+usd(amount)+' − '+usd(a)+' = '+usd(Math.max(0,amount-a))+'</p><p class="hint">'+L('Quote amount − available credit = shortfall','本次报价 − 可用授信 ＝ 差额')+'</p>';}
  function preview(){if(!flow.ccy)return '';if(fault==='fxUnavailable')return note('Exchange rate temporarily unavailable. Retry later.','汇率暂不可用，请稍后重试。','red');if(!flow.fx)flow.fx={value:1,at:D.now(),source:['Token issuance platform · demo','代币发行平台 · 演示'],version:'FX-DEMO-'+(db.serial+1)};const q={ccy:flow.ccy,fx:flow.fx};return dl([[L('Settlement amount','结算金额'),CF.fmtAmt(D.current(pFlow()).amount/flow.fx.value)+' '+flow.ccy]])+snapshot(q);}
  function quoteView(){const p=pFlow(),d=D.current(p),c=credit(p);if(!d||d.state!=='open')return note('This request no longer accepts quotes. Close this window to view the current state.','当前需求已不再接受报价，请关闭弹窗查看最新状态。','warn');return section(L('Credit information','授信信息'),dl([[L('Request ID','需求编号'),E(d.id)],[L('Request amount','需求金额'),usd(d.amount)],[L('Collateral coverage','质押覆盖状态'),L('Sufficient','充足')],[L('Available credit','本机构可用授信'),usd(available(c))],[L('Remaining after quote','报价成功后余量'),usd(available(c)-d.amount)]]))+'<details class="ls-history"><summary>'+L('Credit details and history','授信详情与历史')+'</summary>'+section(L('Company information','企业基本信息'),companyView())+creditInfo(p)+creditHistory(c)+'</details>'+section(L('This quote','本次报价表单'),dl([[L('Financing amount','融资金额'),usd(d.amount)+'<div class="hint">'+L('Full financing only. Amount cannot be changed.','不支持部分融资，金额不可修改。')+'</div>']])+'<div class="cq-grid"><div class="field"><label for="cq-ccy">'+L('Settlement currency *','结算币种 *')+'</label><select id="cq-ccy" class="inp" data-cq-field="ccy"><option value="">'+L('Choose currency','请选择币种')+'</option>'+['USD','USDT','USDC'].map(c=>'<option '+(flow.ccy===c?'selected':'')+'>'+c+'</option>').join('')+'</select></div>'+field('rate','Annual interest rate (%) *','年化利率（%）*',flow.rate,'text','inputmode="decimal"')+'</div>'+preview()+'<p class="hint">'+L('Interest calculation follows the financing contract signed by both parties.','计息规则以双方签署的融资合同为准。')+'</p>'+dl([[L('Repayment type','还款类型'),L('Quarterly interest; principal and remaining interest at maturity','按季付息；到期还本付息')],[L('Final repayment date','最终还款日'),date(p.expires)],[L('Quote validity','报价有效期'),L('168 hours from successful submission','自提交成功起 168 小时')]]));}

  function region(key,en,zh,value=''){const codes='AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW'.split(' '),names=new Intl.DisplayNames([S.lang==='zh'?'zh-CN':'en'],{type:'region'});return '<div class="field"><label for="cq-'+key+'">'+L(en,zh)+'</label><select class="inp" id="cq-'+key+'" data-cq-field="'+key+'"><option value="">'+L('Select country / region','请选择国家 / 地区')+'</option>'+codes.map(c=>'<option value="'+c+'" '+(c===value?'selected':'')+'>'+E(names.of(c))+'</option>').join('')+'</select></div>';}
  function accountView(q){const a=q.progress.account;let body;if(q.ccy!=='USD')body=dl([[L('Currency / network','币种 / 网络'),q.ccy+' · ETH'],[L('Corporate digital address','企业统一数币地址'),wallet?'<span class="mono">0x00000000000000000000000000000000000000a1</span>':L('No address registered','尚未登记地址')]])+(!wallet?note('Register your corporate address before accepting.','请先完成企业数币地址登记。','warn')+B('profile','Corporate address registration','企业地址登记'):'');else body='<div class="cq-grid">'+field('name','Beneficiary name *','收款人名称 *',a.name)+region('addressCountry','Beneficiary country / region *','收款人国家 / 地区 *',a.addressCountry)+field('addressCity','Beneficiary city *','收款人城市 *',a.addressCity)+field('addressLine','Beneficiary street address *','收款人详细地址 *',a.addressLine)+field('iban','Account number / IBAN *','收款账号 / IBAN *',a.iban)+field('bank','Beneficiary bank *','收款行名称 *',a.bank)+field('bankCity','Bank city *','收款行城市 *',a.bankCity)+field('swift','SWIFT / BIC *','SWIFT / BIC *',a.swift)+region('country','Bank country / region *','收款行国家 / 地区 *',a.country)+'</div><details class="ls-history"><summary>'+L('Intermediary bank (optional)','中转行 / 代理行（选填）')+'</summary><p class="hint">'+L('Complete this if your bank requires an intermediary to receive foreign currency. Ask your bank if unsure.','若开户行需要通过中转行接收外币汇款，请填写；不确定时请咨询开户行。')+'</p><div class="cq-grid">'+field('interSwift','Intermediary SWIFT','中转行 SWIFT',a.interSwift)+field('interName','Intermediary bank name','中转行名称',a.interName)+field('interAccount','Account at intermediary','在中转行账号',a.interAccount)+'</div></details>'+note('Only format and company-name consistency are checked. Bank account authenticity and remittance routes are not verified.','平台仅检查格式与户名一致性，不核验账户真实性或汇路可达性。');if(q.ccy==='USD'&&a.swift?.length>=6&&a.country&&a.swift.slice(4,6).toUpperCase()!==a.country.toUpperCase())body+=note('The SWIFT country differs from the bank country. Check the receiving details; you may continue.','SWIFT 国家段与收款行国家不同，请核对收款信息；此提醒不阻断办理。','warn');return body+check('confirmed','I confirm these receiving details for this financing business.','我确认本笔融资使用以上收款信息。',q.progress.confirmed);}
  function uploadView(q){const r=q.progress;return '<p>'+L('Upload the contract signed and stamped offline. PDF, JPG or PNG; up to 10 MB per file and 5 files in total.','上传线下签署盖章件。支持 PDF、JPG、PNG，单文件不超过 10 MB，最多 5 个。')+'</p><label class="field">'+L('Signed documents *','签署盖章件 *')+'<input id="cq-files" class="inp" type="file" accept=".pdf,.jpg,.jpeg,.png" multiple></label><ul class="cq-files">'+r.uploads.map(f=>'<li><span>'+E(f.name)+' · '+CF.fmtAmt(f.size/1024)+' KB</span>'+B('remove','Remove','移除',f.id)+'</li>').join('')+'</ul>'+note('The platform collects files and checks their format, size and count only. It does not verify authenticity or legal validity. The funder checks them before disbursement.','平台仅收取文件并检查格式、大小与数量，不审核真伪及法律效力；资金方将在放款前核验。')+check('declared','I confirm the uploaded contract terms match the summary.','我确认所上传合同的商务条款与本页摘要一致。',r.declared)+fees(q);}
  function response(q){const p=D.project(q.project),n=D.numbers(p),r=q.progress;return countdown(q)+dl([[L('Funder','报价机构'),institution(q.fund)],[L('Institution qualification','机构资质概况'),L('Registered financing institution · demonstration','已登记融资机构 · 演示')],[L('Business ID','融资业务编号'),q.id],[L('Amount / annual rate','金额 / 年化利率'),usd(q.amount)+' · '+q.rate+'%']])+(n.gap?note('Current coverage gap: '+usd(n.gap)+'. Add collateral; submitting an application does not immediately restore coverage.','当前覆盖缺口：'+usd(n.gap)+'。请追加质押，提交申请不会即时补足覆盖。','warn')+B('pledge','Add collateral','追加质押'):'')+'<details class="ls-history"><summary>'+L('View full quote and current collateral','查看完整报价与当前抵押物')+'</summary>'+terms(q)+'</details><ol class="cq-progress">'+[[1,'Receiving account','收款账户'],[2,'Terms summary','商务摘要'],[3,'Signed documents','签署盖章件']].map(s=>'<li aria-current="'+(r.step===s[0]?'step':'false')+'">'+s[0]+'. '+L(s[1],s[2])+'</li>').join('')+'</ol>'+section(L(['','Confirm receiving account','Read the terms summary','Upload signed documents'][r.step],['','确认收款账户','查看商务条款摘要','上传签署盖章件'][r.step]),r.step===1?accountView(q):r.step===2?'<div id="cq-summary">'+terms(q,true)+'</div><div class="ls-row">'+B('copy','Copy summary','复制摘要')+B('print','Print summary','打印摘要')+'</div>':uploadView(q));}
  Q.layers={'cq-flow':()=>{const p=pFlow(),q=qFlow(),c=p&&credit(p);let title='',html='',foot=B('close','Cancel','取消');const loading=busy?note('Submitting…','正在提交…'):'';if(['intent','credit','quote','confirm'].includes(flow.stage)&&!creditWritable())return {title:L('Access unavailable','无法办理'),html:note('Your identity changed. Close and reopen with the correct account.','身份已变化，请关闭后以正确账号重新办理。','warn'),foot:B('close','Close','关闭')};
    if(flow.stage==='intent'){title=L('Credit required before quoting','报价前需核定授信');html=flow.mode==='new'?note('No credit limit has been established for this asset holder. Continue to establish one?','尚未对本资产方核定授信，是否现在核定？'):flow.mode==='renew'?note('The credit expired on '+date(c.expires)+'. Continue to reassess?','原授信已于 '+date(c.expires)+' 到期，是否重新核定？'):difference(p)+note('Increase the credit limit to cover this quote?','是否追加授信额度以覆盖本次报价？');html='<p class="cq-company-name">'+company(p)+'</p>'+html;html+='<p>'+L('Continue opens the credit form. Cancel returns to project details.','确认后进入额度编辑，取消返回项目详情。')+'</p>';foot+=B('intent','Continue','确认','',true);}
    if(flow.stage==='credit'){title=L('Credit before quotation','报价前核定授信');html=creditEditor();foot=B('close','Cancel','取消')+B('save-credit','Save credit and continue','保存授信并继续','',true,busy||flow.discard);}
    if(flow.stage==='quote'){title=L('Financing quote','融资报价');html=quoteView();foot+=B('review-quote','Review quote','确认报价条款','',true,busy);}
    if(flow.stage==='confirm'){title=L('Confirm and submit quote','确认提交报价');html=dl([[L('Amount','融资金额'),usd(D.current(p).amount)],[L('Settlement','结算金额'),CF.fmtAmt(D.current(p).amount/flow.fx.value)+' '+flow.ccy],[L('Annual interest rate','年化利率'),flow.rate+'%']])+snapshot({ccy:flow.ccy,fx:flow.fx})+note('Once submitted, this quote cannot be changed or withdrawn. The request is locked to your institution; other funders cannot quote.','提交后不可修改或撤回，需求将锁定至本机构，其他机构不能报价。','warn')+'<p>'+L('In-flight quotes will increase by '+usd(D.current(p).amount)+'. If not acted on within 168 hours, this quote expires and that amount is released. Only the asset holder can reject it earlier.','本机构在途报价金额增加 '+usd(D.current(p).amount)+'。168 小时不处理将自动失效并释放；提前解除只能由资产方拒绝。')+'</p>';foot=B('back-quote','Back','返回修改')+B('submit','Confirm submission','确认提交','',true,busy);}
    if(flow.stage==='respond'){title=L('Respond to quote','报价确认');html=response(q);foot=B('reject','Reject quote','拒绝报价')+B('close','Save and close','暂存并关闭');if(q.progress.step>1)foot+=B('prev','Previous','上一步');foot+=q.progress.step<3?B('next','Confirm and continue','确认并继续','',true,busy):B('accept','Confirm acceptance','确认接受','',true,busy);}
    if(flow.stage==='reject'){title=L('Reject this quote','拒绝融资报价');html=dl([[L('Financing business ID','融资业务编号'),q.id],[L('Amount','融资金额'),usd(q.amount)]])+note('The reason is visible to the quoting institution. This quote will end; its in-flight credit will be released.','拒绝原因对报价机构可见；本笔报价终结并释放在途报价金额。','warn')+'<div class="field"><label for="cq-reason">'+L('Reason (1–200 characters) *','拒绝原因（1～200 字）*')+'</label><textarea class="inp" id="cq-reason" data-cq-field="reason" maxlength="200">'+E(flow.reason||'')+'</textarea></div>';foot=B('back-response','Back','返回')+B('reject-confirm','Confirm rejection','确认拒绝','',true,busy);}
    if(flow.stage==='history'){title=L('Financing quote','融资报价');html=CF.tag(q.state==='rejected'||q.state==='expired'?'warn':'',status(q))+countdown(q)+terms(q)+(q.done?dl([[L('Result time','处理时间'),time(q.done)],[L('Reason','原因'),q.state==='rejected'&&!related(q)?'—':reason(q)||'—']]):'');if(related(q)&&q.state==='funding'){html+=section(L('Signed documents','签署盖章件'),q.progress.uploads.map(f=>'<p>'+E(f.name)+' '+B('file','Open','打开',f.id)+'</p>').join(''))+section(L('Receiving details','收款信息'),q.ccy==='USD'?dl(Object.entries(q.progress.account).map(([k,v])=>[L(accountLabels[k]?.[0]||k,accountLabels[k]?.[1]||k),E(v)])):dl([[L('Network / address','网络 / 地址'),'ETH · 0x00000000000000000000000000000000000000a1']]));}foot=B('close','Close','关闭');}
    if(flow.stage==='unavailable'){title=L('Unable to continue','当前无法继续');html=note('No new quote was created. Any credit already established remains effective.','未生成新报价；已成功核定的授信仍然生效。','warn');foot=B('close','Back to project','返回项目详情');}
    if(flow.stage==='profile'){title=L('Corporate details','企业资料');html=note('The corporate profile service is unavailable in this prototype. Contact your administrator to complete registered names or the corporate address, then retry.','当前原型未连接企业资料服务。请联系管理员补齐登记名称或企业地址后重试。','warn');foot=B('back-response','Return to quote','返回报价');}
    return {title,html:'<div class="cq-flow">'+html+loading+(flow.stage==='credit'?'':err())+'</div>',foot};},'cq-copy':data=>({title:L('Select and copy summary','选择并复制摘要'),html:'<textarea class="inp cq-copy" readonly>'+E(data)+'</textarea>',foot:B('back-response','Return','返回')})};
  const accountLabels={name:['Beneficiary name','收款人名称'],addressCountry:['Beneficiary country / region','收款人国家 / 地区'],addressCity:['Beneficiary city','收款人城市'],addressLine:['Beneficiary street address','收款人详细地址'],iban:['Account number / IBAN','收款账号 / IBAN'],bank:['Bank name','银行名称'],bankCity:['Bank city','收款行城市'],swift:['SWIFT / BIC','SWIFT / BIC'],country:['Bank country','银行国家'],interSwift:['Intermediary SWIFT','中转行 SWIFT'],interName:['Intermediary bank','中转行名称'],interAccount:['Intermediary account','中转行账号']};
  function normalize(v){return v.toLowerCase().replace(/\blimited\b/g,'ltd').replace(/\bcompany\b/g,'co').replace(/[\s.,，。()（）-]/g,'');}
  function accountValid(q){const a=q.progress.account;if(q.ccy!=='USD'){if(!wallet)return failure('Register the corporate digital address first.','请先登记企业统一数币地址。');}else{for(const key of ['name','addressCountry','addressCity','addressLine','iban','bank','bankCity','swift','country'])if(!a[key]?.trim())return failure('Complete '+accountLabels[key][0]+'.','请填写'+accountLabels[key][1]+'。',key);const names=['Demo Asset Company A','演示资产企业 A'];if(!names.some(n=>normalize(n)===normalize(a.name)))return failure('Beneficiary “'+a.name+'” does not match the registered names: '+names.join(' / ')+'. Update corporate details before continuing.','填写户名「'+a.name+'」与本企业已登记名称「'+names.join(' / ')+'」不一致，请先补登企业资料。','name');if(!/^[A-Za-z0-9]{8}([A-Za-z0-9]{3})?$/.test(a.swift))return failure('SWIFT / BIC must contain 8 or 11 letters or digits.','SWIFT / BIC 须为 8 位或 11 位字母数字。','swift');}if(!q.progress.confirmed)return failure('Confirm this receiving account for this business.','请显式确认本笔收款信息。');return true;}
  function quoteValid(){if(!canQuote(pFlow()))return false;if(!['USD','USDT','USDC'].includes(flow.ccy))return failure('Choose a settlement currency.','请选择结算币种。','ccy');if(!/^\d+(\.\d{1,2})?$/.test(flow.rate)||+flow.rate<=0||+flow.rate>100)return failure('Enter an annual rate above 0 and at most 100, with up to 2 decimal places.','请输入大于 0、不超过 100 且最多两位小数的年化利率。','rate');if(fault==='fxUnavailable'||!flow.fx)return failure('Exchange rate temporarily unavailable. Retry later.','汇率暂不可用，请稍后重试。');const settlement=D.current(pFlow()).amount/flow.fx.value;if(Math.abs(settlement*100-Math.round(settlement*100))>0.000001)return failure('The settlement amount cannot be confirmed at this time. Retry after settlement details are available.','当前暂无法确认结算金额，请待结算资料完整后重试。');return true;}
  function stillWaiting(q){Q.sweep();if(S.role!=='asset'||!D.mine(D.project(q.project)))return failure('You cannot act for this asset holder.','您无权代表该资产方操作。');if(q.state!=='waiting'){flow.stage='history';return failure('This quote has already been processed: '+status(q)+'.','该报价已处理：'+status(q)+'。');}return true;}
  function asyncAction(fn){if(busy)return;busy=true;const identity=S.role;setTimeout(()=>{try{if(identity!==S.role)failure('The identity changed. Retry with the correct account.','身份已变化，请以正确账号重试。');else if(fault==='submitFailure')failure('Submission failed. Your entries are retained; retry later.','提交失败，已保留填写内容，请稍后重试。');else fn();}finally{busy=false;save();CF.render();}},450);}
  Q.onAct=(act,v)=>{if(act==='ls-quote'){startQuote(D.project(v));return true;}if(act==='ls-handoff'&&v==='quote'){const p=pNow(),q=p&&active(p);if(q)beginReview(q);else CF.toast(L('This quote is no longer awaiting confirmation.','报价已不再待确认，请查看融资记录。'));return true;}if(!act.startsWith('cq-'))return false;act=act.slice(3);if(busy)return true;problem='';invalid='';const p=pFlow(),q=qFlow();
    if(act==='close')requestClose();
    if(act==='keep-editing')flow.discard=false;
    if(act==='discard-credit')closeFlow();
    if(act==='company-retry'&&['credit','quote'].includes(flow.stage))retryCompany();
    if(act==='credit-preview'||act==='credit-download')creditFileAction(v,act==='credit-preview');
    if(['credit-remove','credit-retry'].includes(act)&&flow.stage==='credit'&&creditWritable()){const f=flow.agreements.find(f=>f.id===v);if(f){if(act==='credit-remove'){flow.agreements=flow.agreements.filter(f=>f.id!==v);creditFiles.delete(v);}else uploadAgreement(f);}}
    if(act==='intent')creditForm(flow.mode);
    if(act==='save-credit'&&flow.stage==='credit'&&!flow.discard)submitCredit();
    if(act==='review-quote'&&quoteValid())flow.stage='confirm';
    if(act==='back-quote')flow.stage='quote';
    if(act==='submit'&&quoteValid())asyncAction(()=>{if(!canQuote(p)||!checkCoverage(p,true)){flow.stage='unavailable';return;}if(fault==='competing'){const d=D.current(p);d.state='quoted';d.institution=['Demo Capital B','演示资金机构 B'];d.quoteAt=D.iso();p.state='locked';fault='normal';flow.stage='unavailable';failure('Another institution has already quoted. No quote was created for your institution.','已被其他机构抢先报价，本机构未生成报价。');return;}const c=credit(p),d=D.current(p);if(available(c)<d.amount||c.expires<day()){creditForm(c.expires<day()?'renew':'increase');failure('Credit changed. Review the current limit.','授信已变化，请核对最新额度。');return;}if(fault==='fxChanged'){flow.fx={...flow.fx,value:flow.ccy==='USD'?1:0.8,version:flow.fx.version+'-R',at:D.now()};fault='normal';failure('The exchange rate changed. Review the updated settlement amount and confirm again.','汇率已变化，请核对更新后的结算金额并再次确认。');return;}const at=D.now(),x={id:'FB-DEMO-'+(++db.serial),project:p.id,owner:p.owner,demand:d.id,amount:d.amount,rate:flow.rate,ccy:flow.ccy,settlement:d.amount/flow.fx.value,fx:{...flow.fx},fund,at,end:at+168*H,repay:p.expires,state:'waiting',progress:{account:{...(db.lastAccounts[p.owner]||{})},confirmed:false,viewed:false,declared:false,uploads:[],step:1}};db.quotes.push(x);d.state='quoted';d.rate=flow.rate;d.currency=flow.ccy;d.institution=fund==='fund-a'?['Demo Capital A','演示资金机构 A']:['Demo Capital B','演示资金机构 B'];d.quoteAt=new Date(at).toISOString();p.state='locked';notify(x,'submitted');flow.quote=x.id;flow.stage='history';CF.toast(L('Quote submitted.','报价已提交。'));});
    if(act==='history'){flow={quote:v,project:db.quotes.find(q=>q.id===v).project};open('history');}
    if(act==='respond')beginReview(db.quotes.find(q=>q.id===v));
    if(act==='next'&&stillWaiting(q)){if(q.progress.step===1&&accountValid(q)){q.progress.step=2;q.progress.viewed=true;q.progress.disclosedAt=D.now();}else if(q.progress.step===2)q.progress.step=3;}
    if(act==='prev')q.progress.step=Math.max(1,q.progress.step-1);
    if(act==='reject'&&stillWaiting(q)){flow.reason='';flow.stage='reject';}
    if(act==='back-response')flow.stage='respond';
    if(act==='reject-confirm'&&stillWaiting(q)){if(!flow.reason?.trim()||[...flow.reason.trim()].length>200)failure('Enter a reason of 1–200 characters.','请输入 1～200 字拒绝原因。','reason');else asyncAction(()=>{if(stillWaiting(q)){finish(q,'rejected',flow.reason.trim());flow.stage='history';}});}
    if(act==='accept'&&stillWaiting(q)){if(accountValid(q)&&q.progress.viewed){if(!q.progress.uploads.length||!q.progress.declared)failure('Upload at least one signed document and confirm that its terms match the summary.','请上传至少一份签署盖章件并确认条款一致性声明。');else asyncAction(()=>{if(stillWaiting(q)){finish(q,'funding','');if(q.ccy==='USD')db.lastAccounts[q.owner]={...q.progress.account};flow.stage='history';}});}}
    if(act==='remove'){q.progress.uploads=q.progress.uploads.filter(f=>f.id!==v);files.delete(v);q.progress.declared=false;}
    if(act==='profile')flow.stage='profile';
    if(act==='pledge'){CF.closeLayer();setTimeout(()=>document.querySelector('[data-act=ls-tab][data-v=global]')?.click(),0);}
    if(act==='copy'){const text=document.getElementById('cq-summary').innerText;navigator.clipboard?.writeText(text).then(()=>CF.toast(L('Summary copied.','摘要已复制。'))).catch(()=>CF.openLayer('modal','cq-copy',text));if(!navigator.clipboard)CF.openLayer('modal','cq-copy',text);}
    if(act==='print'){document.body.classList.add('cq-printing');window.print();document.body.classList.remove('cq-printing');}
    if(act==='file'&&related(q)){const f=files.get(v);if(f){const url=URL.createObjectURL(f),a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else CF.toast(L('The local file is no longer available after reload.','刷新后本地文件不可用，请向业务经办人索取原件。'));}
    if(act==='event'){const target=db.quotes.find(x=>x.id===v);if(target){S.demo=false;location.hash='#/project/'+target.project;setTimeout(()=>{if(target.state==='waiting'&&S.role==='asset')beginReview(target);else{flow={quote:target.id,project:target.project};open('history');}},100);}}
    if(act==='demo')demo(v);
    save();return true;
  };
  Q.publicInfo=p=>{const list=db.quotes.filter(q=>q.project===p.id);if(!list.length)return creditOverview(p);return creditOverview(p)+'<section class="card"><div class="card-head"><h2 class="ls-subheading">'+L('Financing quotes','融资报价')+'</h2></div><div class="card-b cq-records">'+[...list].reverse().map(q=>'<article class="cq-record"><div class="ls-row"><b>'+institution(q.fund)+'</b>'+CF.tag(q.state==='waiting'?'accent':'',status(q))+'<span class="mono">'+q.id+'</span></div><p class="cq-amount mono">'+usd(q.amount)+' <span class="muted">· '+q.rate+'%</span></p>'+countdown(q)+(q.state==='expired'||q.state==='rejected'&&related(q)?'<p>'+reason(q)+' · '+time(q.done)+'</p>':'')+'<div class="ls-row">'+B('history','View quote details','查看报价详情',q.id)+(q.state==='waiting'&&D.mine(p)?B('respond','Accept / reject','接受 / 拒绝',q.id,true):'')+'</div></article>').join('')+'</div></section>';};
  Q.rowInfo=p=>{const q=active(p);return q?'<div class="cell-sub">'+institution(q.fund)+'</div><div class="cell-sub">'+L('Locked: ','锁定起始：')+time(q.at)+'</div>'+countdown(q):'';};
  Q.enhance=()=>{const panel=document.getElementById('demoPanel');if(S.demo&&!panel.querySelector('.cq-demo')){const el=document.createElement('div');el.className='cq-demo ls-review';el.innerHTML='<h5>'+L('Credit and quotes · review tools','授信报价 · 评审工具')+'</h5><div class="ls-row">'+[['new','No credit','无授信'],['increase','Insufficient credit','额度不足'],['renew','Expired credit','授信到期'],['enough','Sufficient credit','额度充足'],['waiting','Pending quote','待接受报价'],['rejected','Rejected quote','已拒绝报价'],['soon','Less than 24 hours','临期不足 24 小时'],['timeout','+168 hours','推进 168 小时'],['requestVoid','Request expires','需求失效'],['short','Current coverage warning','当前覆盖提醒'],['other','Other funder','切换其他资金方'],['wallet','Toggle address','切换地址有无'],['denied','Rejected write','越权写入反馈']].map(x=>B('demo',x[1],x[2],x[0])).join('')+'</div><div class="field"><label for="cq-fault">'+L('Next submission','下次提交')+'</label><select class="inp" id="cq-fault">'+[['normal','Normal','正常'],['fxUnavailable','Rate unavailable','汇率不可用'],['coverageUnavailable','Coverage unavailable','覆盖校验不可用'],['coverage','Coverage invalidated','覆盖不足终检'],['competing','Competing quote wins','他方抢先报价'],['fxChanged','Rate changes','汇率变化'],['submitFailure','Submission failure','提交失败'],['uploadFailure','File upload failure','文件上传失败']].map(x=>'<option value="'+x[0]+'" '+(fault===x[0]?'selected':'')+'>'+L(x[1],x[2])+'</option>').join('')+'</select></div><p class="why">'+L('Events and credentials are simulated. Files stay on this device. Reload retains progress, but local file contents are not persisted.','事件与企业资料均为演示。文件仅留在本机；刷新保留进度，不保存文件内容。')+'</p>';const events=db.events.filter(e=>{const q=db.quotes.find(q=>q.id===e.quote);return q&&(S.role==='asset'&&D.mine(D.project(q.project))&&e.who==='asset'||S.role==='fund'&&e.who===fund);});el.innerHTML+='<h5>'+L('Notification event previews','通知事件预览')+'</h5>'+(events.length?events.map(e=>'<p>'+L({submitted:'Quote received',expiring:'Quote expiring soon',expired:'Quote expired',accepted:'Quote accepted',rejected:'Quote rejected'}[e.event],{submitted:'收到融资报价',expiring:'融资报价即将到期',expired:'融资报价已失效',accepted:'融资报价已接受',rejected:'融资报价已拒绝'}[e.event])+' · '+E(e.quote)+' '+B('event','View','查看',e.quote)+'</p>').join(''):'<p class="why">'+L('No events for this identity.','当前身份暂无事件。')+'</p>');el.insertAdjacentHTML('beforeend','<div class="field"><label for="cq-company-state">'+L('Company information scenario','企业资料场景')+'</label><select class="inp" id="cq-company-state">'+[['complete','Complete','完整'],['partial','Partially unavailable','部分未提供'],['loading','Loading','加载中'],['error','Load failed','加载失败'],['unconfirmed','Owner unconfirmed','企业归属不明'],['denied','Permission denied','无办理权限']].map(x=>'<option value="'+x[0]+'" '+(companyState===x[0]?'selected':'')+'>'+L(x[1],x[2])+'</option>').join('')+'</select></div>');panel.prepend(el);}const modal=document.querySelector('.modal:has(.cq-flow)');document.getElementById('portal').inert=!!modal;if(modal){if(busy)modal.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true);if(flow.stage==='credit'&&invalid){const target=document.getElementById('cq-'+invalid);if(target){target.setAttribute('aria-invalid','true');target.focus();}}if(flow.discard){modal.querySelector('.cq-discard')?.scrollIntoView({block:'start'});}modal.querySelectorAll('[aria-invalid=true]').forEach(x=>x.setAttribute('aria-describedby','cq-error'));if(invalid==='name'&&!modal.querySelector('[data-act=cq-profile]'))modal.querySelector('#cq-error')?.insertAdjacentHTML('beforeend',B('profile','Update registered name','补登企业名称'));}if(S.layer?.key==='cq-flow'&&qFlow()?.state!=='waiting'&&['respond','reject'].includes(flow.stage)){flow.stage='history';CF.render();}};
  function demo(v){let p=pNow()||D.projects[0];if(['new','increase','renew','enough','waiting','rejected'].includes(v)){D.seed();p=D.projects[0];S.role=v==='waiting'||v==='rejected'?'asset':'fund';fund='fund-a';const c=credit(p);if(v==='new'){db.quotes.filter(q=>q.fund==='fund-a').forEach(q=>finish(q,'expired','timeout'));db.credits=[];}if(v==='increase')c.total=used(c)+c.principal+100000;if(v==='renew')c.expires='2020-01-01';if(v==='waiting'||v==='rejected')p=D.project('FP-DEMO-003');if(v==='rejected')finish(active(p),'rejected',L('The financing terms do not match our current needs.','融资条款不符合当前需求。'));S.layer=null;location.hash='#/project/'+p.id;}
    if(v==='other'){fund=fund==='fund-a'?'fund-b':'fund-a';S.role='fund';S.layer=null;}
    if(v==='soon'){const q=active(p);if(q){D.offset+=Math.max(0,q.end-D.now()-23*H);Q.sweep();}}
    if(v==='timeout'){D.offset+=168*H;Q.sweep();}
    if(v==='requestVoid'){D.tokens.filter(t=>t.pool===p.id).forEach(t=>t.valid=false);D.recompute(p);}
    if(v==='short'){p.balance=800000;D.tokens.filter(t=>t.pool===p.id).forEach(t=>t.valid=false);p.coverageAt=D.iso();}
    if(v==='wallet')wallet=!wallet;
    if(v==='denied')CF.toast(L('Permission denied. No business state changed.','无权执行，业务状态未改变。'));
    save();
  }
  document.addEventListener('input',e=>{const el=e.target,k=el.dataset.cqField;if(!k)return;invalid='';if(['respond','profile'].includes(flow.stage)&&qFlow()){qFlow().progress.account[k]=el.value;qFlow().progress.confirmed=false;qFlow().progress.declared=false;const box=document.querySelector('[data-cq-check=confirmed]');if(box)box.checked=false;save();}else flow[k]=el.value;if(k==='total'&&flow.mode==='increase'){const a=document.getElementById('cq-adjusted');if(a)a.textContent=L('Adjusted limit: ','调整后额度：')+usd(credit(pFlow()).total+Number(el.value||0));}});
  document.addEventListener('change',e=>{const el=e.target;if(el.id==='cq-agreements'){pickAgreements([...el.files]);return;}if(el.id==='cq-company-state')companyState=el.value;if(el.id==='cq-ccy'){flow.ccy=el.value;flow.fx=null;CF.render();}if(el.id==='cq-fault')fault=el.value;if(['country','addressCountry'].includes(el.dataset.cqField)&&qFlow()){qFlow().progress.account[el.dataset.cqField]=el.value;qFlow().progress.confirmed=false;save();CF.render();}if(el.dataset.cqCheck){qFlow().progress[el.dataset.cqCheck]=el.checked;save();}if(el.id==='cq-files'){const q=qFlow();problem='';for(const f of el.files){if(!/\.(pdf|jpe?g|png)$/i.test(f.name)||!['application/pdf','image/jpeg','image/png',''].includes(f.type))failure('Unsupported file: '+f.name+'. Use PDF, JPG or PNG.','文件格式不支持：'+f.name+'，请使用 PDF、JPG 或 PNG。');else if(f.size>10*1024*1024)failure('File exceeds 10 MB: '+f.name,'文件超过 10 MB：'+f.name);else if(q.progress.uploads.length>=5)failure('Up to 5 files are allowed. Successful uploads were retained.','最多上传 5 个文件，已保留其他成功文件。');else if(fault==='uploadFailure')failure('Upload failed: '+f.name+'. Retry this file.','文件上传失败：'+f.name+'，请重试。');else{const id='file-'+(++db.serial);q.progress.uploads.push({id,name:f.name,size:f.size});files.set(id,f);}}q.progress.declared=false;save();CF.render();}});
  document.addEventListener('keydown',e=>{const dialog=document.querySelector('.modal:has(.cq-flow)');if(!dialog||e.key!=='Tab')return;const els=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,summary,a[href]')].filter(x=>x.getClientRects().length),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}});
  Q.beforeAct=(act,event)=>{if(act!=='closelayer'||S.layer?.key!=='cq-flow')return false;if(event?.type==='click'&&event.target.closest('[data-stop]'))return false;if(busy)return true;requestClose();return true;};
  Q.deepAction=action=>{const p=pNow();if(!p)return;if(action==='quote')startQuote(p);if(action==='quote_confirm'){const q=active(p);if(q)beginReview(q);else CF.toast(L('This quote is no longer awaiting confirmation.','报价已不再待确认。'));}};
  setInterval(()=>{if(Q.sweep())CF.render();else document.querySelectorAll('.cq-clock').forEach(el=>{const q=db.quotes.find(q=>q.id===el.dataset.cqQuote);if(q)el.outerHTML=countdown(q);});},1000);
})(window.CF);
